// ---- React to the toggle ----
{
  const isSf = dfView === "sf object";
  const svg = d3.select(dfSvg);
  svg.select(".sfhdr").style("opacity", isSf ? 1 : 0);
  svg.selectAll(".col-geometry").style("opacity", isSf ? 1 : 0);
